const privateApplications = ["A", "B", "C"];
const companyProcess = [
  { title: "Understand", detail: "We get clear on the business, the constraint, and the decision that actually matters." },
  { title: "Build", detail: "We shape robust software with the product judgment and engineering discipline it deserves." },
  { title: "Improve", detail: "We measure, learn, and keep making the work more useful after it is released." },
];

useScrollTimeline(root, ({ gsap }) => {
  gsap.fromTo(".reference-hero", { opacity: 0 }, { opacity: 1, duration: .55, ease: "power2.out" });
