  gsap.fromTo(".manifesto-grid", { opacity: 0, y: 44 }, { opacity: 1, y: 0, duration: 0.8, ease: "power3.out", scrollTrigger: { trigger: ".manifesto", start: "top 76%" } });
  const track = root.value?.querySelector<HTMLElement>(".work-track");
  if (track && window.innerWidth > 850) gsap.to(track, { x: () => -(track.scrollWidth - window.innerWidth), ease: "none", scrollTrigger: { trigger: ".work-rail", start: "top top", end: () => `+=${Math.max(track.scrollWidth - window.innerWidth + 80, 760)}`, pin: true, scrub: 1, invalidateOnRefresh: true } });
  else gsap.fromTo(".work-card", { opacity: 0, y: 30 }, { opacity: 1, y: 0, stagger: 0.12, duration: 0.65, ease: "power3.out", scrollTrigger: { trigger: ".work-track", start: "top 80%" } });
  gsap.fromTo(".reference-applications", { opacity: 0, y: 54 }, { opacity: 1, y: 0, duration: 0.9, ease: "power3.out", scrollTrigger: { trigger: ".reference-applications", start: "top 78%" } });
  gsap.fromTo(".native-application-card", { opacity: 0, y: 28 }, { opacity: 1, y: 0, stagger: 0.1, duration: 0.65, ease: "power3.out", scrollTrigger: { trigger: ".reference-applications", start: "top 75%" } });
  gsap.fromTo(".reference-company", { opacity: 0, y: 54 }, { opacity: 1, y: 0, duration: 0.9, ease: "power3.out", scrollTrigger: { trigger: ".reference-company", start: "top 78%" } });
  gsap.fromTo(".native-process", { opacity: 0, y: 24 }, { opacity: 1, y: 0, stagger: 0.1, duration: 0.6, ease: "power3.out", scrollTrigger: { trigger: ".reference-company", start: "top 78%" } });
  gsap.fromTo(".ai-brief", { opacity: 0, y: 36 }, { opacity: 1, y: 0, duration: 0.75, ease: "power3.out", scrollTrigger: { trigger: ".ai-brief", start: "top 80%" } });
});
